function system = systemEquations(X,dirichlet,p,IT,rho_star)
% Defines the system that has to be solved to determine the Fourier
% amplitudes that appear in the Taylor expansions of R and Z
% Unknowns : X = [Rm, Zm, kappam, dR0_a, dZ0_a, de_a, dS2_a, dA2_a, dS3_a, dA3_a]

[~,~,~,~,~,mu0] = pc_dke_yp;

X = num2cell(X) ;
[Rm, Zm, kappam, dR0_a, dZ0_a, de_a, dS2_a, dA2_a, dS3_a, dA3_a] = X{:} ;

dirich=num2cell(dirichlet) ;
[R0_a,Z0_a,a,e_a,S2_a,A2_a,S3_a,A3_a] = dirich{:} ;

pcell = num2cell(p) ;
[d2p_0, d4p_0] = pcell{:} ;

ITcell = num2cell(IT) ;
[d2IT_0, d4IT_0, d6IT_0] = ITcell{:} ;

% Boundary conditions
[d2R0_0,d4R0_0] = boundaryCondition_R0_like(a,R0_a,Rm,dR0_a,rho_star) ;
[d2Z0_0,d4Z0_0] = boundaryCondition_R0_like(a,Z0_a,Zm,dZ0_a,rho_star) ;
[d2e_0,d4e_0] = boundaryCondition_R0_like(a,e_a,kappam,de_a,rho_star) ;
[dS2_0,d3S2_0] = boundaryCondition_S2_like(a,S2_a,dS2_a,rho_star) ;
[dA2_0,d3A2_0] = boundaryCondition_S2_like(a,A2_a,dA2_a,rho_star) ;
[dS3_0,d3S3_0] = boundaryCondition_S2_like(a,S3_a,dS3_a,rho_star) ;
[dA3_0] = boundaryCondition_S2_like(a,A3_a,dA3_a,rho_star) ;

% MagneticAxisRadialShiftEquation
system(1) = kappam.^2.*(1+(-8).*pi.^2.*kappam.^(-2).*(1+kappam.^2).^2.*mu0.^(-1).*d2IT_0.^(-2).*d2p_0)+Rm.*(1+3.*kappam.^2).*d2R0_0+(-8).*Rm.*dS2_0;
% RadialShiftEquation
system(2) = 3.*((-13)+5.*kappam.^2+12.*(1+kappam.^2).^(-1))+(-3).*Rm.*d2R0_0.*(6.*Rm.^2.*(5+kappam.^2+(-4).*(1+kappam.^2).^(-1)).*d2R0_0.^2+Rm.^2.*kappam.^(-2).*((-6)+18.*kappam.^2+24.*(1+kappam.^2).^(-1)).*d2Z0_0.^2)+32.*pi.^2.*Rm.^2.*(1+kappam.^2).^2.*mu0.^(-1).*d2IT_0.^(-2).*d4p_0+(-6).*Rm.^3.*(1+3.*kappam.^2).*d4R0_0+(-18).*Rm.*d2R0_0.*((-1).*Rm.^2.*kappam.^(-1).*((-13)+3.*kappam.^2+12.*(1+kappam.^2).^(-1)).*d2e_0+8.*Rm.^2.*kappam.^(-1).*(11+3.*kappam.^2+(-8).*(1+kappam.^2).^(-1)).*d2Z0_0.*dA2_0)+144.*a.^(-1).*Rm.^2.*(3.*Rm.*kappam.^(-1).*((-1)+kappam.^2).*d2Z0_0+8.*Rm.*(2+kappam.^2).*dA2_0).*dA3_0+(-1).*Rm.^2.*d2IT_0.^(-1).*d4IT_0.*((-1)+5.*kappam.^2+Rm.*(6+18.*kappam.^2).*d2R0_0+(-48).*Rm.*dS2_0)+12.*Rm.^2.*dA2_0.^2.*(101+19.*kappam.^2+(-84).*(1+kappam.^2).^(-1)+24.*Rm.*(13+3.*kappam.^2+(-28).*(1+kappam.^2).^(-1)).*dS2_0)+3.*Rm.^2.*kappam.^(-1).*d2e_0.*((-41)+kappam.^2+36.*(1+kappam.^2).^(-1)+(-48).*Rm.*(5+kappam.^2+(-6).*(1+kappam.^2).^(-1)).*dS2_0)+(-3).*Rm.^2.*kappam.^(-2).*d2Z0_0.^2.*((-9)+kappam.^2+12.*(1+kappam.^2).^(-1)+(-48).*Rm.*(5+3.*kappam.^2+(-2).*(1+kappam.^2).^(-1)).*dS2_0)+3.*Rm.^2.*d2R0_0.^2.*((-43)+15.*kappam.^2+36.*(1+kappam.^2).^(-1)+(-288).*Rm.*(1+(-1).*(1+kappam.^2).^(-1)).*dS2_0)+(-24).*Rm.^2.*kappam.^(-1).*d2Z0_0.*dA2_0.*(27+kappam.^2+(-24).*(1+kappam.^2).^(-1)+(-12).*Rm.*((-13)+3.*kappam.^2+16.*(1+kappam.^2).^(-1)).*dS2_0)+12.*Rm.*dS2_0.*((-43)+kappam.^2+36.*(1+kappam.^2).^(-1)+Rm.*dS2_0.*(19+29.*kappam.^2+36.*(1+kappam.^2).^(-1)+24.*Rm.*(7+5.*kappam.^2+(-20).*(1+kappam.^2).^(-1)).*dS2_0))+3.*Rm.*d2R0_0.*((-31)+49.*kappam.^2+36.*(1+kappam.^2).^(-1)+(-24).*Rm.^2.*((-37)+3.*kappam.^2+28.*(1+kappam.^2).^(-1)).*dA2_0.^2+8.*Rm.*dS2_0.*(2.*((-17)+3.*kappam.^2+18.*(1+kappam.^2).^(-1))+9.*Rm.*(1+kappam.^2+4.*(1+kappam.^2).^(-1)).*dS2_0))+24.*a.^(-1).*Rm.^2.*((-5)+7.*kappam.^2+(-24).*Rm.*d2R0_0+12.*Rm.*(9+7.*kappam.^2).*dS2_0).*dS3_0+24.*pi.^2.*(1+kappam.^2).^2.*mu0.^(-1).*d2IT_0.^(-2).*d2p_0.*(1+4.*(Rm.^2.*kappam.^(-1).*d2e_0+Rm.*d2R0_0+(-2).*Rm.*dS2_0+(-4).*(Rm.^2.*dA2_0.^2+Rm.^2.*dS2_0.^2+a.^(-1).*Rm.^2.*dS3_0)))+24.*Rm.^3.*(3+kappam.^2).*d3S2_0;
% MagneticAxisVerticalShiftEquation
system(3) = Rm.*kappam.^(-1).*(3+kappam.^2).*d2Z0_0+4.*Rm.*((-3)+kappam.^2).*dA2_0;
% VerticalShiftEquation
system(4) = 3.*Rm.*kappam.^(-1).*d2Z0_0.*(Rm.^2.*((-1)+3.*kappam.^2+4.*(1+kappam.^2).^(-1)).*d2R0_0.^2+Rm.^2.*kappam.^(-2).*(5+kappam.^2+(-4).*(1+kappam.^2).^(-1)).*d2Z0_0.^2)+Rm.^3.*kappam.^(-1).*(3+kappam.^2).*d4Z0_0+(-24).*Rm.^3.*kappam.^(-1).*((-14)+kappam.^2+12.*(1+kappam.^2).^(-1)).*d2e_0.*dA2_0+12.*Rm.*(Rm.^2.*(11+3.*kappam.^2+(-8).*(1+kappam.^2).^(-1)).*d2R0_0.^2+(-3).*Rm.^2.*kappam.^(-2).*(9+kappam.^2+(-8).*(1+kappam.^2).^(-1)).*d2Z0_0.^2).*dA2_0+Rm.^2.*d2IT_0.^(-1).*d4IT_0.*(Rm.*kappam.^(-1).*(3+kappam.^2).*d2Z0_0+4.*Rm.*((-3)+kappam.^2).*dA2_0)+(-24).*a.^(-1).*Rm.^2.*dA3_0.*(((-1)+kappam.^2).*(1+3.*Rm.*d2R0_0)+4.*Rm.*(5+kappam.^2).*dS2_0)+12.*Rm.^2.*d2R0_0.*dA2_0.*(7+kappam.^2+(-8).*(1+kappam.^2).^(-1)+(-4).*Rm.*((-13)+3.*kappam.^2+16.*(1+kappam.^2).^(-1)).*dS2_0)+(-24).*Rm.*dA2_0.*((-5)+kappam.^2+4.*(1+kappam.^2).^(-1)+4.*Rm.^2.*(26+kappam.^2+(-28).*(1+kappam.^2).^(-1)).*dA2_0.^2+Rm.*dS2_0.*((-11)+2.*kappam.^2+16.*(1+kappam.^2).^(-1)+4.*Rm.*(20+3.*kappam.^2+(-20).*(1+kappam.^2).^(-1)).*dS2_0))+(-6).*Rm.*kappam.^(-1).*d2Z0_0.*(3+kappam.^2+(-2).*(1+kappam.^2).^(-1)+6.*Rm.^2.*((-55)+kappam.^2+52.*(1+kappam.^2).^(-1)).*dA2_0.^2+2.*Rm.*dS2_0.*(4.*(1+kappam.^2+(-1).*(1+kappam.^2).^(-1))+(-1).*Rm.*(59+27.*kappam.^2+(-20).*(1+kappam.^2).^(-1)).*dS2_0))+3.*Rm.*kappam.^(-1).*d2Z0_0.*((-1).*Rm.^2.*kappam.^(-1).*(21+5.*kappam.^2+(-12).*(1+kappam.^2).^(-1)).*d2e_0+Rm.*d2R0_0.*((-1)+kappam.^2+4.*(1+kappam.^2).^(-1)+(-16).*Rm.*(5+3.*kappam.^2+(-2).*(1+kappam.^2).^(-1)).*dS2_0))+48.*a.^(-1).*Rm.^2.*(2.*Rm.*kappam.*d2Z0_0+Rm.*(7+kappam.^2).*dA2_0).*dS3_0+4.*Rm.^3.*((-5)+kappam.^2).*d3A2_0;
% MagneticAxisElongationEquation
system(5) = 3.*(1+kappam.^(-2)+4.*(1+kappam.^2).^(-1))+3.*Rm.^2.*kappam.^(-1).*(1+5.*kappam.^(-2)+12.*(1+kappam.^2).^(-1)).*d2e_0+(-3).*Rm.^2.*(3+3.*kappam.^(-2)+(-4).*(1+kappam.^2).^(-1)).*d2R0_0.^2+(-3).*Rm.^2.*kappam.^(-2).*(5+21.*kappam.^(-2)+4.*(1+kappam.^2).^(-1)).*d2Z0_0.^2+Rm.^2.*(1+(-1).*kappam.^(-2)).*d2IT_0.^(-1).*d4IT_0+48.*Rm.^2.*kappam.^(-1).*(9.*kappam.^(-2)+4.*(1+kappam.^2).^(-1)).*d2Z0_0.*dA2_0+(-12).*Rm.^2.*(5+41.*kappam.^(-2)+28.*(1+kappam.^2).^(-1)).*dA2_0.^2+(-24).*pi.^2.*kappam.^(-2).*(1+kappam.^2).^2.*mu0.^(-1).*d2IT_0.^(-2).*d2p_0.*(1+(-4).*Rm.*d2R0_0+8.*Rm.*dS2_0)+3.*Rm.*d2R0_0.*(3+kappam.^(-2)+4.*(1+kappam.^2).^(-1)+16.*Rm.*(3+3.*kappam.^(-2)+2.*(1+kappam.^2).^(-1)).*dS2_0)+12.*Rm.*dS2_0.*(3+(-5).*kappam.^(-2)+4.*(1+kappam.^2).^(-1)+(-1).*Rm.*(19+23.*kappam.^(-2)+20.*(1+kappam.^2).^(-1)).*dS2_0)+(-120).*a.^(-1).*Rm.^2.*(1+(-1).*kappam.^(-2)).*dS3_0;
% ElongationEquation
